R.append(T(3128,"हॉट मल्ड पंच","सेब बहुमुखी खाद्य पदार्थ हैं जो आपको स्वस्थ रखने में ऊँचे अंक पाते हैं। ताज़े सेब के स्वाद का कोई मुकाबला नहीं। पतझड़ की ठंड में, किडनी-अनुकूल हॉट मल्ड पंच के एक अच्छे कप से ज़्यादा आरामदायक क्या हो सकता है, जो क्रैनबेरी और सेब के रस का दालचीनी और लौंग की हल्की खुशबू वाला स्वादिष्ट मिश्रण है? यह एक ऐसा पेय है जिसकी खुशबू भी उतनी ही अच्छी है जितना उसका स्वाद।","14","1 कप",
["6 कप Ocean Spray® Natural Pure100% बिना मीठा क्रैनबेरी जूस","8 कप सेब का रस","1/2 कप ब्राउन शुगर","4 दालचीनी की डंडियाँ, टूटी हुई","1-1/2 छोटा चम्मच साबुत लौंग"],
["सामग्री को एक बड़े बर्तन या क्रॉक पॉट में मिलाएँ।","हल्का उबाल आने तक गरम करें और गरम परोसें।"],
["हॉट मल्ड पंच को परोसने के समय तक क्रॉक पॉट में धीमी आँच पर रखा जा सकता है। यह घर को पतझड़ की खुशबू से भरने का बेहतरीन तरीका है।","कम कार्बोहाइड्रेट वाले संस्करण के लिए, मधुमेह वाले लोग कम कैलोरी वाला क्रैनबेरी जूस कॉकटेल और Splenda® ब्राउन शुगर ब्लेंड इस्तेमाल कर सकते हैं। कार्बोहाइड्रेट = प्रति सर्विंग 24 ग्राम, 1-1/2 कार्बोहाइड्रेट विकल्प।"],["2 फल, कम पोटैशियम"]))
R.append(T(3139,"फ्रॉस्ट ऑन द पंपकिन पाई","नेब्रास्का की DaVita रीनल आहार विशेषज्ञ डायने द्वारा भेजी गई फ्रॉस्ट ऑन द पंपकिन पाई रेसिपी एक अनूठी किडनी-अनुकूल हैलोवीन मिठाई है। इसे अपनी अगली पार्टी में ले जाएँ।","16 (2 पाई)","एक पाई का 1/8 हिस्सा",
["2-1/2 कप ग्राहम क्रैकर का चूरा","6 बड़े चम्मच चीनी","2 छोटे चम्मच दालचीनी","1/2 छोटा चम्मच जायफल","1/2 छोटा चम्मच पिसी लौंग","2/3 कप बिना नमक का मक्खन","16 औंस Pillsbury® Creamy Supreme® Vanilla Frosting","1 कप खट्टी क्रीम (सावर क्रीम)","1 कप डिब्बाबंद कद्दू","1/2 छोटा चम्मच अदरक","3/4 कप हेवी क्रीम"],
["ओवन को 350º F पर गरम करें।","एक छोटे कटोरे में ग्राहम क्रैकर का चूरा, चीनी, 1 छोटा चम्मच दालचीनी, जायफल, 1/4 छोटा चम्मच लौंग और पिघला हुआ मक्खन मिलाएँ; मिलने तक चलाएँ। टॉपिंग के लिए 4 बड़े चम्मच चूरा अलग रख लें।","बचे हुए चूरे को दो 9-इंच के पाई पैन के तले और किनारों पर दबाकर बिछाएँ।","6 मिनट बेक करें। ठंडा करें।","एक बड़े कटोरे में फ्रॉस्टिंग, खट्टी क्रीम, कद्दू, 1 छोटा चम्मच दालचीनी, अदरक और 1/4 छोटा चम्मच लौंग मिलाएँ। भरावन को तैयार क्रस्ट में डालें।","मिक्सिंग बाउल और हैंड मिक्सर के बीटर को 15 मिनट के लिए फ्रीज़र में रखें। हेवी क्रीम को कटोरे में डालें और नरम शिखर बनने तक फेंटें। इसे बाँटकर हर पाई के ऊपर समान रूप से फैलाएँ।","अलग रखा हुआ ग्राहम क्रैकर का चूरा ऊपर से छिड़कें।","जमने के लिए फ्रीज़ करें, फिर परोसने के समय तक फ्रिज में रखें।","बची हुई मिठाई को फ्रिज में रखें।"],
["आप ग्राहम क्रैकर का चूरा खरीद सकते हैं या 36 ग्राहम क्रैकर वर्गों को कुचलकर खुद बना सकते हैं।","वसा घटाने के लिए हेवी क्रीम की जगह Reddi-Wip® डेयरी व्हिप्ड टॉपिंग का उपयोग करें और चरण #6 छोड़ दें। पाई पर फैलाने के बजाय, परोसने से ठीक पहले हर सर्विंग पर लगभग 2 बड़े चम्मच स्प्रे करें। वसा घटकर 3 ग्राम हो जाती है।"],["2 स्टार्च","4 वसा","1 उच्च कैलोरी"]))
R.append(T(3141,"घर का बना फॉस्फोरस-मुक्त बेकिंग पाउडर","किडनी रोग वाले और डायलिसिस पर रहने वाले लोगों के लिए कई खाद्य पदार्थ प्रतिबंधित हैं, लेकिन कैनसस की DaVita रीनल आहार विशेषज्ञ मैरी की घर के बने फॉस्फोरस-मुक्त बेकिंग पाउडर की रेसिपी की बदौलत बिस्किट, टॉर्टिला, पैनकेक और वैफ़ल जैसे खाद्य पदार्थ फिर से आपके मेनू में शामिल हो गए हैं।","6","प्रति रेसिपी लगभग 1 बड़ा चम्मच (सर्विंग की संख्या और अन्य सामग्री के आधार पर बदलता है)",
["1/4 कप क्रीम ऑफ टार्टर","2 बड़े चम्मच बेकिंग सोडा"],
["क्रीम ऑफ टार्टर और बेकिंग सोडा को महीन छलनी से एक साथ छान लें।","उपयोग के समय तक कमरे के तापमान पर वायुरोधी जार या बैगी में रखें।"],
["ध्यान दें कि मात्रा और पोषक तत्व पूरी रेसिपी में इस्तेमाल होते हैं, इसलिए पोषक तत्वों के मान बँट जाएँगे। अधिकांश रेसिपी में पूरी रेसिपी के लिए एक बड़े चम्मच से कम बेकिंग पाउडर लगता है।","इस बेकिंग पाउडर रेसिपी में क्रीम ऑफ टार्टर और बेकिंग सोडा का अनुपात 2-से-1 है। किसी रेसिपी में बाज़ार के बेकिंग पाउडर के एक बड़े चम्मच की जगह 2 छोटे चम्मच क्रीम ऑफ टार्टर और 1 छोटा चम्मच बेकिंग सोडा इस्तेमाल करें।","केक, क्विक ब्रेड, मफ़िन, टॉर्टिला, पैनकेक और वैफ़ल बनाते समय आप इस मिश्रण का उपयोग बाज़ार के बेकिंग पाउडर के समान अनुपात में कर सकते हैं।","क्रीम ऑफ टार्टर टार्टरिक एसिड का पोटैशियम एसिड नमक है, जो वाइन बनाने का एक उप-उत्पाद है। एक छोटे चम्मच में 495 mg पोटैशियम होता है। फॉस्फोरस युक्त बेकिंग पाउडर की जगह बेकिंग सोडा के साथ क्रीम ऑफ टार्टर का उपयोग करते समय ध्यान रखें कि भोजन में पोटैशियम की मात्रा अधिक होगी लेकिन फॉस्फोरस बहुत कम होगा।"],["0"]))
R.append(T(3143,"एप्पल बार्स","एक सेहतमंद किडनी-अनुकूल मिठाई जो स्वादिष्ट भी हो, उसे आगे बढ़ाया जाना चाहिए। और मिनेसोटा की सैंड्रा अपने स्वादिष्ट, कम पोटैशियम वाले और सेहत के लिए अच्छे एप्पल बार्स के साथ ठीक यही कर रही हैं।","18","1 बार, 3\" x 3\"",
["2 मध्यम सेब","3/4 कप बिना नमक का मक्खन","1 कप दानेदार चीनी","1 कप खट्टी क्रीम (सावर क्रीम)","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक","2 कप मैदा","1/2 कप ब्राउन शुगर","1 छोटा चम्मच दालचीनी","2 बड़े चम्मच दूध","1 कप पिसी चीनी"],
["ओवन को 350° F पर पहले से गरम करें।","सेब छीलकर काट लें।","1/2 कप मक्खन और दानेदार चीनी या दानेदार चीनी के विकल्प को एक साथ क्रीमी होने तक फेंटें।","खट्टी क्रीम, वनीला, बेकिंग सोडा, नमक और मैदा डालें। मिलाने के लिए चलाएँ; कटे हुए सेब डालें।","घोल को चिकनाई लगे 9” x 13” बेकिंग पैन में डालें।","एक छोटे कटोरे में 2 बड़े चम्मच नरम मक्खन, ब्राउन शुगर और दालचीनी को एक साथ मसलकर चूरा बनाएँ। इसे घोल के ऊपर छिड़कें।","35 से 40 मिनट बेक करें। पूरी तरह ठंडा होने दें।","आइसिंग बनाने के लिए 2 बड़े चम्मच पिघला हुआ मक्खन, दूध (या दूध का विकल्प) और पिसी चीनी मिलाएँ। ऊपर से छिड़कें और मिठाई को 18 बार्स में काटें।"],
["1 मध्यम सेब से 1 कप कटा हुआ सेब मिलता है।","मधुमेह वाले लोग दानेदार चीनी की जगह दानेदार चीनी का विकल्प इस्तेमाल कर सकते हैं और आइसिंग छोड़ सकते हैं, जिससे कार्बोहाइड्रेट की मात्रा घटकर प्रति सर्विंग 19 ग्राम (1 कार्बोहाइड्रेट विकल्प) हो जाएगी। मात्रा के आकार को लेकर सावधानी बरतें।"],["1/2 फल, कम पोटैशियम","1 स्टार्च","2 वसा","1 उच्च कैलोरी"]))
R.append(T(3146,"केकड़े से भरी सेलरी के टुकड़े","पार्टी के स्टार्टर के लिए काफ़ी शानदार, फिर भी झटपट स्नैक के लिए काफ़ी आसान। DaVita की आहार विशेषज्ञ टीम के केकड़े से भरी सेलरी के टुकड़ों का यही सार है। अपने अगले आयोजन में इस किडनी-अनुकूल स्टार्टर को आज़माएँ।","4","3 टुकड़े",
["सेलरी की 4 डंठलें (मध्यम 8-इंच)","1/4 कप केकड़े का मांस","1 बड़ा चम्मच लाल प्याज़","2 छोटे चम्मच मेयोनेज़","1/2 छोटा चम्मच नींबू का रस","1/4 छोटा चम्मच पेपरिका"],
["सेलरी की डंठलों के सिरे काटें। केकड़े के मांस का पानी निथारकर उसे रेशे-रेशे कर लें। प्याज़ को बारीक काटें।","एक छोटे कटोरे में केकड़े का मांस, प्याज़, मेयोनेज़ और नींबू का रस मिलाएँ।","हर सेलरी की डंठल में केकड़े के मिश्रण का 1 बड़ा चम्मच भरें।","हर सेलरी की डंठल को 3 टुकड़ों में काटें।","परोसने से पहले केकड़े से भरे सेलरी के टुकड़ों पर पेपरिका छिड़कें।"],
["रेसिपी के विश्लेषण में डिब्बाबंद केकड़े का मांस शामिल है। यदि पसंद हो तो ताज़ा या जमा हुआ इस्तेमाल करें।","पार्टियों या सामाजिक आयोजनों में परोसने के लिए रेसिपी को दोगुना या तिगुना करें।"],["1 सब्ज़ी, कम पोटैशियम"]))
R.append(T(3149,"बैंगन से बने फ्रेंच फ्राइज़","DaVita की आहार विशेषज्ञ जिल के कुरकुरे बैंगन फ्रेंच फ्राइज़ आलू का एक रोमांचक किडनी-अनुकूल विकल्प हैं और फाइबर का उत्कृष्ट स्रोत हैं।","6","7-8 टुकड़े",
["1 मध्यम बैंगन","1 कप 1% कम वसा वाला दूध","2 बड़े अंडे","3/4 कप कॉर्नस्टार्च","3/4 कप सूखा बिना मसाले का ब्रेड क्रम्ब्स","3 छोटे चम्मच सूखा Hidden Valley Original Ranch® सलाद ड्रेसिंग और सीज़निंग मिक्स","1 छोटा चम्मच Tabasco® हॉट सॉस (वैकल्पिक)","1/2 कप कैनोला तेल"],
["बैंगन को छीलकर 3/4” मोटी, 4” लंबी डंडियों में काटें। धोकर थपथपाकर सुखा लें।","एक मध्यम कटोरे में दूध और अंडे अच्छी तरह मिलने तक मिलाएँ; हॉट सॉस मिलाएँ।","एक चौड़े, उथले कटोरे में कॉर्नस्टार्च, ब्रेड क्रम्ब्स और सूखा रैंच सलाद ड्रेसिंग मिक्स मिलाएँ।","फ्राइंग पैन में तेज़ आँच पर तेल गरम करें।","बैंगन की डंडियों को अंडे के मिश्रण में डुबोएँ और फिर हर टुकड़े को ब्रेड क्रम्ब्स के मिश्रण में लपेटें।","तेल में डालें, नियमित रूप से पलटते रहें और 3 मिनट या सुनहरा भूरा होने तक तलें।","पेपर टॉवल पर निथार लें और तुरंत परोसें।"],
["वसा और कोलेस्ट्रॉल की मात्रा घटाने के लिए 1/2 कप कम कोलेस्ट्रॉल वाला अंडा उत्पाद इस्तेमाल करें।","फ्रेंच फ्राइड आलू में पोटैशियम ज़ुकिनी से बने फ्रेंच फ्राइज़ की तुलना में बहुत अधिक होता है।"],["1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]))
R.append(T(3151,"टेम्पे पिटा सैंडविच","अगली बार जब आपको कुरकुरे और मेवे जैसे स्वाद वाले सैंडविच की इच्छा हो, तो शाकाहारियों के पसंदीदा टेम्पे पिटा सैंडविच आज़माएँ। किडनी-अनुकूल आहार में फिट होने के अलावा, टेम्पे पिटा सैंडविच में कोलेस्ट्रॉल और संतृप्त वसा कम है और प्रति सर्विंग 5.5 ग्राम फाइबर के साथ फाइबर अधिक है।","4","3 स्लाइस टेम्पे के साथ 1/2 पिटा",
["8 औंस टेम्पे","2 बड़े चम्मच तिल का तेल","2 बड़े चम्मच बाल्सेमिक सिरका","1 छोटा प्याज़","1 लाल शिमला मिर्च","1/2 कप मशरूम","2 पिटा ब्रेड, 6-इंच आकार की","4 छोटे चम्मच मेयोनेज़"],
["टेम्पे को 12 स्लाइस में काटें। प्याज़, शिमला मिर्च और मशरूम को पतले स्लाइस में काटें।","एक बड़ी स्किलेट में मध्यम आँच पर 1 बड़ा चम्मच तिल का तेल गरम करें। कटा हुआ टेम्पे डालें और हर तरफ 3 से 4 मिनट भूरा होने तक पकाएँ। बाल्सेमिक सिरका डालें और एक मिनट पकाएँ; पलटें और एक मिनट और पकाएँ। टेम्पे को स्किलेट से निकाल लें।","बचा हुआ तिल का तेल स्किलेट में डालें और मध्यम आँच पर गरम करें। प्याज़, शिमला मिर्च और मशरूम डालें और नरम होने तक पकाएँ।","पिटा को आधा काटें और खोलकर जेब (पॉकेट) बना लें। हर आधे हिस्से पर 1 छोटा चम्मच मेयोनेज़ लगाएँ। हर पिटा के आधे हिस्से में टेम्पे के 3 टुकड़े और सब्ज़ी के मिश्रण का 1/4 हिस्सा डालें। तुरंत परोसें।"],
["स्वाद में बदलाव के लिए तिल के तेल की जगह अपना पसंदीदा फ्लेवर्ड तेल इस्तेमाल करें।","टेम्पे साबुत सोयाबीन को चावल या बाजरे के साथ मिलाकर, फिर किण्वित करके बनाया जाता है। इसका स्वाद मेवे जैसा होता है और यह पकाते समय डाले गए मैरिनेड या मसालों के स्वाद को सोख लेता है।"],["1-1/2 मांस","1 स्टार्च","1-1/2 सब्ज़ी, मध्यम पोटैशियम","2 वसा"]))
R.append(T(3153,"अनानास चावल","अपने अगले किडनी-अनुकूल साइड डिश में मीठा, उष्णकटिबंधीय स्वाद जोड़ें। अनानास चावल बनाना आसान है और अच्छा प्रभाव छोड़ता है।","6","1/2 कप",
["1 कप बिना मीठे रस में डिब्बाबंद अनानास के टुकड़े","3/4 कप लंबे दाने वाला सफेद चावल, बिना पका","1-1/4 कप पानी"],
["अनानास का रस निथारें और अलग रख लें।","अनानास, चावल, अलग रखा अनानास का रस और पानी एक सॉसपैन में मिलाएँ।","उबाल आने दें, ढक दें और आँच धीमी कर दें। 20 से 25 मिनट तक धीमी आँच पर पकाएँ, जब तक सारा पानी सोख न लिया जाए और चावल नरम न हो जाएँ।"],
["किसी भी करी रेसिपी के साथ परोसें।"],["1 स्टार्च","1/2 फल, कम पोटैशियम"]))
R.append(T(3167,"शतावरी (एस्पैरागस) स्प्रेड","यह शतावरी स्प्रेड की एक किडनी आहार रेसिपी है, जिससे स्वादिष्ट फिंगर सैंडविच बनते हैं और जो पार्टियों में डिप के रूप में भी हिट होती है। एक अलग स्वाद के अनुभव के लिए इस रेसिपी में किडनी-अनुकूल शतावरी की जगह खीरे का उपयोग किया जा सकता है।","16","2 बड़े चम्मच",
["6 औंस क्रीम चीज़","8 औंस डिब्बाबंद शतावरी, कम सोडियम वाली","1/4 कप मेयोनेज़","2 बड़े चम्मच प्याज़","1 बड़ा चम्मच नींबू का रस"],
["क्रीम चीज़ को नरम होने के लिए बाहर रख दें।","शतावरी का पानी अच्छी तरह निथार दें।","सभी सामग्री को फ़ूड प्रोसेसर में मिलाएँ और मिलने तक प्रोसेस करें। कटोरे में निकालें, ढकें और रात भर फ्रिज में रखें।","स्प्रेड को कम सोडियम वाले क्रैकर के साथ परोसें या फिंगर सैंडविच बनाएँ।"],
["डिब्बाबंद शतावरी की जगह ताज़ी या जमी हुई शतावरी इस्तेमाल की जा सकती है। इसे पानी में तब तक उबालें जब तक शतावरी इतनी नरम न हो जाए कि काँटे से मसली जा सके।","यह रेसिपी शतावरी की जगह कटे हुए खीरे से भी बनाई जा सकती है।"],["1/2 सब्ज़ी, कम पोटैशियम","1 वसा"]))
R.append(T(3168,"चिले कोलोराडो सॉस (बेसिक लाल मिर्च सॉस)","यह चिले कोलोराडो सॉस की एक किडनी-अनुकूल रेसिपी है, जो और कुछ नहीं बल्कि बेसिक लाल मिर्च सॉस है। यही आपकी चिली रेसिपी को उसका स्वादिष्ट, विशिष्ट स्वाद देता है।","10","1/4 कप",
["3 बड़े चम्मच प्याज़","लहसुन की 1 कली","2 बड़े चम्मच कैनोला तेल","2 बड़े चम्मच मैदा","1 छोटा चम्मच पिसा जीरा","1/2 छोटा चम्मच पिसा ओरेगैनो","1/2 कप सूखी लाल मिर्च का पाउडर (एंको या पासिया)","2-1/2 कप पानी","1/4 छोटा चम्मच नमक","1 छोटा चम्मच चीनी"],
["प्याज़ को बारीक काटें और लहसुन को बारीक काटें।","एक मध्यम सॉसपैन में कैनोला तेल गरम करें और प्याज़ और लहसुन को नरम होने तक भूनें।","मैदा डालकर मिलने तक चलाएँ; जीरा और ओरेगैनो डालें। 3 मिनट पकाएँ और चलाते रहें, फिर आँच से उतार लें।","मिर्च पाउडर डालें और मिलाने के लिए चलाएँ। पैन को वापस आँच पर रखें और 2-1/2 कप पानी, नमक और चीनी डालें।","लगातार चलाते हुए सॉस में उबाल आने तक गरम करें। आँच धीमी करें और 5 मिनट तक धीमी आँच पर पकाएँ।","उपयोग के समय तक सॉस को फ्रिज में रखें। इससे 2-1/2 कप सॉस बनता है।"],
["मिर्च पाउडर आसानी से जल जाता है, इसलिए बार-बार चलाएँ और ध्यान रखें कि आपका पैन बहुत ज़्यादा गरम न हो।","सूखी मिर्चों से मिर्च पाउडर बनाएँ या बाज़ार से खरीदा मिर्च पाउडर इस्तेमाल करें। ध्यान रखें, मिर्च पाउडर में नमक मिलाया गया होता है इसलिए सोडियम की मात्रा अधिक होगी। यदि मिर्च पाउडर इस्तेमाल करें तो 1/4 छोटा चम्मच नमक न डालें।","सॉस फ्रिज में 1 सप्ताह तक चलता है।","इस सॉस का उपयोग चिले कोलोराडो रेसिपी बनाने के लिए करें।"],["1/2 सब्ज़ी, मध्यम पोटैशियम","1/2 वसा"]))
